<script setup lang="ts">import type{Manager,Priority,Department}from'../types';defineProps<{priorities:Priority[];chef:string;department:string;search:string;managers:Manager[];count:number}>();const emit=defineEmits(['update:priorities','update:chef','update:department','update:search','reset']);function toggle(p:Priority,arr:Priority[]){emit('update:priorities',arr.includes(p)?arr.filter(x=>x!==p):[...arr,p])}</script><template><section class="filters"><div class="filter-group"><span class="label">Priorité</span><div class="chips"><button v-for="p in ['HAUTE','MOYENNE','BASSE']" :key="p" class="chip" :class="{active:priorities.includes(p as Priority)}" @click="toggle(p as Priority,priorities)">{{p==='HAUTE'?'Haute':p==='MOYENNE'?'Moyenne':'Basse'}}</button></div></div><label>Chef de projet<select :value="chef" @change="emit('update:chef',($event.target as HTMLSelectElement).value)"><option value="">Tous</option><option v-for="m in managers" :value="m.name">{{m.name}}</option></select></label><label>Département<select :value="department" @change="emit('update:department',($event.target as HTMLSelectElement).value)"><option value="">Tous</option><option v-for="d in ['STR','ECO','FLU','ELEC','VRD','BIM']">{{d}}</option></select></label><label class="search">Recherche<input :value="search" @input="emit('update:search',($event.target as HTMLInputElement).value)" placeholder="N° projet ou intitulé…"></label><div class="filter-footer"><button class="link" @click="emit('reset')">Réinitialiser les filtres</button><strong>{{count}} ligne(s) affichée(s)</strong></div></section></template>
